-2-data-sampling-and-variation-in-data-and-sampling\nOpenStax — Measures of the Location of the Data: https://openstax.org/books/introductory-statistics-2e/pages/2-3-measures-of-the-location-of-the-data\nOpenStax — Informal Fallacies (correlation and causation): https://openstax.org/books/introduction-philosophy/pages/5-5-informal-fallacies","color":"#62836B","icon":"📊"},"cards":[{"id":"0ef07565-f57e-58e5-afe5-934b831ead2e","front":"Statistic","back":"A numerical summary calculated from sample data.","hint":"A poll’s average is an estimate, not the population value.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"3b6f2d9c-ecf2-5bb3-b28b-6a9b9e1e8e02","front":"Standard deviation","back":"The square root of variance, measuring spread in the original units.","hint":"Unlike variance, it can be stated in centimeters or seconds.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"466b7e71-9a9a-5096-864c-87be99b5a363","front":"Pearson correlation","back":"Pearson’s correlation measures the direction and strength of a linear relationship between two numerical variables.","hint":"A curved relationship can be strong even when this is near zero.","explanation":"Correlation alone does not establish that one variable causes the other.","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"6a0ce94d-7e9c-504a-980b-de62e1a0ae2f","front":"Range","back":"The largest value minus the smallest value.","hint":"Focus on the two extremes.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"6e908abf-ec92-5ff8-a22c-ed12bb63b714","front":"Variance","back":"A measure of spread based on squared deviations from the mean.","hint":"Squaring prevents positive and negative deviations from cancelling.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"7bebe102-8fc2-5fc3-ba65-2a2daa1759aa","front":"Parameter","back":"A numerical characteristic of a population.","hint":"Distinguish the whole group from the observed subset.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"95a31694-2d56-5b0d-a9e2-adc978a37f67","front":"Simple random sample","back":"A sample selected so every possible group of its size has an equal chance of selection.","hint":"Think of a thoroughly mixed draw without replacement.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"a10fabef-0d89-5b5a-94fc-a831d75f62b2","front":"Sample","back":"A subset of a population selected for study.","hint":"A poll asks some people rather than everyone.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"b58a3c22-eb0e-5920-8437-0f427bee245f","front":"Null hypothesis","back":"A baseline claim about a population or probability model that a statistical test evaluates.","hint":"Often a claim of no difference or no effect.","explanation":"Failing to reject it does not prove it true.","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"bd48b7ef-71f1-586a-b520-34fac17309ce","front":"P-value","back":"Assuming the null hypothesis and test assumptions, the probability of a result at least as extreme as the observed result.","hint":"The probability concerns possible data, not whether a hypothesis is true.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"c3dcdabd-471b-5331-82b7-247b270c9eaf","front":"Median","back":"The middle ordered value, or the average of the two middle values when the count is even.","hint":"Sort the numbers before finding the center.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"cefcd264-3315-5c90-b5e6-b49457984935","front":"Population","back":"The complete group of individuals or items a study concerns.","hint":"","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"dac73d32-5878-53f7-8c48-72001e39c26c","front":"Outlier","back":"An observation unusually far from the rest of the data.","hint":"Check an extreme value before deciding to remove it.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"e00e8b4e-cbc4-538f-bd2c-0a573011eb41","front":"Mode","back":"The value or values occurring most frequently in a data set.","hint":"Can a data set have more than one?","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true},{"id":"e2c2ab3e-bee6-5e94-a402-0451da5b566d","front":"Mean","back":"The sum of numerical values divided by how many values there are.","hint":"Imagine sharing the total equally.","explanation":"","tags":["math","statistics","beginner"],"aiGenerated":true}]},"publishRequest":{"operationId":"31f611b7-a87c-5d79-84a9-41d8f222cc66","deckId":"5f6dabda-e6e8-5290-87a5-e979faeb0128","rightsAccepted":true,"expectedContentHash":"76b415cf3a9eee4857ee2f66153327eca7296620bea52be656d7fe02e33dfa39","showDownloadCount":false,"showUsageStats":false},"payloadHash":"f63550168aa61e218120255cbc5a78d6f9158ad9d285581942c9bee426dfab8e"}]}$recollect_ai_catalog_json$::jsonb;
  publisher_id uuid := (catalog->'publisher'->>'id')::uuid;
  entry jsonb;
  card jsonb;
  existing_publisher record;
  revision_value bigint;
  ordinal_value integer := 0;
  has_new_decks boolean := false;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('recollect.starter-catalog.v1'));
  -- Rerunning the SQL after a normal migration must not restore operator removals or settings.
  IF EXISTS (SELECT 1 FROM recollect.schema_migrations WHERE name='0007_recollect_ai_catalog.sql') THEN
    RETURN;
  END IF;
  -- This is the actual owner tombstone, without inventing an Apple identity for a system publisher.
  IF EXISTS (SELECT 1 FROM recollect.account_deletion_requests WHERE owner_id=publisher_id) THEN
    RETURN;
  END IF;
  SELECT * INTO existing_publisher FROM recollect.users WHERE id=publisher_id FOR UPDATE;
  IF FOUND THEN
    IF existing_publisher.apple_id IS NOT NULL OR existing_publisher.email IS NOT NULL
       OR existing_publisher.name IS DISTINCT FROM catalog->'publisher'->>'name' THEN
      RAISE EXCEPTION 'Recollect AI catalog publisher ID is already owned by another identity';
    END IF;
    IF NOT existing_publisher.is_active THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM recollect.sessions WHERE owner_id=publisher_id)
       OR EXISTS (SELECT 1 FROM recollect.session_families WHERE owner_id=publisher_id) THEN
      RAISE EXCEPTION 'Recollect AI catalog publisher unexpectedly has authentication sessions';
    END IF;
  ELSE
    INSERT INTO recollect.users(id,apple_id,email,name,is_active,created_at)
    VALUES(publisher_id,NULL,NULL,catalog->'publisher'->>'name',true,(catalog->>'createdAt')::timestamptz);
  END IF;

  -- Check every globally unique ID before inserting anything. Never adopt another owner's rows.
  FOR entry IN SELECT value FROM jsonb_array_elements(catalog->'decks') LOOP
    IF EXISTS (
      SELECT 1 FROM recollect.decks d WHERE d.id=(entry->'deck'->>'id')::uuid
      AND (d.owner_id<>publisher_id OR d.data->>'ownerId' IS DISTINCT FROM publisher_id::text
        OR d.data->>'id' IS DISTINCT FROM entry->'deck'->>'id')
    ) THEN RAISE EXCEPTION 'Recollect AI catalog deck ID collision: %',entry->>'slug'; END IF;
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(entry->'cards') c
      JOIN recollect.cards saved ON saved.id=(c->>'id')::uuid
      WHERE saved.owner_id<>publisher_id OR saved.deck_id<>(entry->'deck'->>'id')::uuid
        OR saved.data->>'ownerId' IS DISTINCT FROM publisher_id::text
        OR saved.data->>'deckId' IS DISTINCT FROM entry->'deck'->>'id'
        OR saved.data->>'id' IS DISTINCT FROM c->>'id'
    ) THEN RAISE EXCEPTION 'Recollect AI catalog card ID collision: %',entry->>'slug'; END IF;
    IF EXISTS (
      SELECT 1 FROM recollect.marketplace_listings l
      WHERE (l.id=(entry->>'listingId')::uuid
        AND (l.owner_id<>publisher_id OR l.source_deck_id<>(entry->'deck'->>'id')::uuid))
        OR (l.owner_id=publisher_id AND l.source_deck_id=(entry->'deck'->>'id')::uuid
          AND l.id<>(entry->>'listingId')::uuid)
    ) THEN RAISE EXCEPTION 'Recollect AI catalog listing ID collision: %',entry->>'slug'; END IF;
    IF EXISTS (
      SELECT 1 FROM recollect.marketplace_publish_operations p
      WHERE p.owner_id=publisher_id AND p.operation_id=(entry->'publishRequest'->>'operationId')::uuid
        AND (p.listing_id<>(entry->>'listingId')::uuid OR p.payload_hash<>entry->>'payloadHash')
    ) THEN RAISE EXCEPTION 'Recollect AI catalog publication ID collision: %',entry->>'slug'; END IF;
    IF NOT EXISTS (SELECT 1 FROM recollect.decks WHERE id=(entry->'deck'->>'id')::uuid)
       AND NOT EXISTS (SELECT 1 FROM recollect.marketplace_listings WHERE id=(entry->>'listingId')::uuid) THEN
      has_new_decks := true;
    END IF;
  END LOOP;
  IF NOT has_new_decks THEN RETURN; END IF;

  INSERT INTO recollect.sync_heads(owner_id) VALUES(publisher_id) ON CONFLICT DO NOTHING;
  SELECT revision+1 INTO revision_value FROM recollect.sync_heads WHERE owner_id=publisher_id FOR UPDATE;
  FOR entry IN SELECT value FROM jsonb_array_elements(catalog->'decks') LOOP
    -- Existing catalog rows belong to the operator. Do not refill, republish, or reset them.
    IF EXISTS (SELECT 1 FROM recollect.decks WHERE id=(entry->'deck'->>'id')::uuid)
       OR EXISTS (SELECT 1 FROM recollect.marketplace_listings WHERE id=(entry->>'listingId')::uuid) THEN
      CONTINUE;
    END IF;
    INSERT INTO recollect.decks(owner_id,id,data)
    VALUES(publisher_id,(entry->'deck'->>'id')::uuid,entry->'deck');
    INSERT INTO recollect.changes(owner_id,revision,ordinal,entity,data)
    VALUES(publisher_id,revision_value,ordinal_value,'deck',entry->'deck');
    ordinal_value := ordinal_value+1;
    FOR card IN SELECT value FROM jsonb_array_elements(entry->'cards') LOOP
      INSERT INTO recollect.cards(owner_id,id,deck_id,data,checkpoint,checkpoint_at)
      VALUES(publisher_id,(card->>'id')::uuid,(card->>'deckId')::uuid,card,card->'schedule',
        (catalog->>'createdAt')::timestamptz);
      INSERT INTO recollect.changes(owner_id,revision,ordinal,entity,data)
      VALUES(publisher_id,revision_value,ordinal_value,'card',card);
      ordinal_value := ordinal_value+1;
    END LOOP;
    INSERT INTO recollect.marketplace_listings(
      id,owner_id,source_deck_id,version,snapshot,is_published,show_download_count,show_usage_stats,published_at,updated_at)
    VALUES((entry->>'listingId')::uuid,publisher_id,(entry->'deck'->>'id')::uuid,1,entry->'snapshot',
      true,false,false,(catalog->>'createdAt')::timestamptz,(catalog->>'createdAt')::timestamptz);
    INSERT INTO recollect.marketplace_versions(listing_id,version,snapshot,source_revision,created_at)
    VALUES((entry->>'listingId')::uuid,1,entry->'snapshot',revision_value,(catalog->>'createdAt')::timestamptz);
    INSERT INTO recollect.marketplace_publish_operations(
      owner_id,operation_id,listing_id,version,payload_hash,rights_policy_version,accepted_at)
    VALUES(publisher_id,(entry->'publishRequest'->>'operationId')::uuid,(entry->>'listingId')::uuid,
      1,entry->>'payloadHash',1,(catalog->>'createdAt')::timestamptz);
  END LOOP;
  UPDATE recollect.sync_heads SET revision=revision_value WHERE owner_id=publisher_id;
END
$recollect_ai_catalog$;
